const listPayments = `-- name: ListPayments :many
SELECT p.id, p.receipt_no, p.admission_id, p.student_id, p.amount_paise, p.method, p.reference, p.paid_on, p.proof_upload_id, p.status, p.source, p.submitted_by, p.approved_by, p.approved_at, p.rejection_reason, p.note, p.created_at, a.admission_no, a.counsellor_id, u.name AS student_name, COALESCE(u.phone, '')::text AS student_phone,
       sb.name AS submitted_by_name, ab.name AS approved_by_name, co.name AS counsellor_name,
       pu.mime AS proof_mime, count(*) OVER () AS total_count
FROM payments p
JOIN admissions a ON a.id = p.admission_id
JOIN users u ON u.id = p.student_id
LEFT JOIN users sb ON sb.id = p.submitted_by
LEFT JOIN users ab ON ab.id = p.approved_by
LEFT JOIN users co ON co.id = a.counsellor_id
LEFT JOIN uploads pu ON pu.id = p.proof_upload_id
WHERE ($1::uuid IS NULL OR p.id = $1)
  AND ($2::uuid IS NULL OR p.admission_id = $2)
  AND ($3::text IS NULL OR p.status = $3)
  AND ($4::text IS NULL OR p.method = $4)
  AND ($5::text IS NULL OR p.source = $5)
  AND ($6::date IS NULL OR p.paid_on >= $6)
  AND ($7::date IS NULL OR p.paid_on <= $7)
  AND ($8::text IS NULL OR a.admission_no ILIKE '%' || $8 || '%' OR u.name ILIKE '%' || $8 || '%'
       OR p.reference ILIKE '%' || $8 || '%' OR COALESCE(p.receipt_no, '') ILIKE '%' || $8 || '%')
  AND ($9::uuid IS NULL OR a.counsellor_id = $9 OR a.created_by = $9)
  AND ($10::uuid IS NULL OR a.counsellor_id IN (SELECT cp.user_id FROM counsellor_profiles cp WHERE cp.team_id = $10))
ORDER BY (p.status = 'pending') DESC, p.created_at DESC
LIMIT $12::int OFFSET $11::int
`

